function loadCaseScript(name) {
  return new Promise((resolve, reject) => {
    const script = document.createElement("script");
    script.src = new URL(name, import.meta.url).href;
    script.onload = resolve;
    script.onerror = () => reject(Error("試遊の記録を読み込めません。"));
    document.head.append(script);
  });
}

export async function previewRecord(name) {
  if (Object.hasOwn(bundled, name)) return bundled[name];
  await Promise.all([loadCaseScript("./preview-cases-a.js"), loadCaseScript("./preview-cases-b.js")]);
  const record = amberTimePreviewCasesA[name] ?? amberTimePreviewCasesB[name];
  if (typeof record !== "string") throw Error("試遊の記録がありません。");
  return record;
}
